package parsing

import (
	"bytes"
	"unicode"
	"unicode/utf8"
)

// generatedMarkers are the phrases generators write at the top of a file,
// across ecosystems: "Code generated … DO NOT EDIT" (Go and others),
// "@generated" (Rust, Python, Facebook tools), "<auto-generated>" (C#),
// "GENERATED CODE - DO NOT MODIFY" (Dart), "Generated by Django", and the like.
var generatedMarkers = [][]byte{
	[]byte("@generated"), []byte("code generated"), []byte("generated by"), []byte("generated using"),
	[]byte("do not edit"), []byte("do not modify"), []byte("autogenerated"), []byte("auto-generated"),
	[]byte("automatically generated"),
}

// scaffoldMarkers are written by tools that start a file for its owner to
// edit, such as django-admin startproject at the top of settings.py and
// urls.py. Those files are the project's own code, not generated output.
var scaffoldMarkers = [][]byte{[]byte("django-admin startproject"), []byte("django-admin startapp")}

// GeneratedHeader reports whether the first 512 bytes of content mark the file
// as generated. Markers match case-insensitively and as whole words, so a
// comment about a "regenerated" cache does not count.
func GeneratedHeader(content []byte) bool {
	head := bytes.ToLower(content[:min(len(content), 512)])
	for _, m := range scaffoldMarkers {
		if bytes.Contains(head, m) {
			return false
		}
	}
	for _, m := range generatedMarkers {
		for i := 0; ; {
			j := bytes.Index(head[i:], m)
			if j < 0 {
				break
			}
			start, end := i+j, i+j+len(m)
			if !letterBefore(head, start) && !letterAt(head, end) {
				return true
			}
			i = start + 1
		}
	}
	return false
}

func letterBefore(b []byte, i int) bool {
	r, _ := utf8.DecodeLastRune(b[:i])
	return i > 0 && unicode.IsLetter(r)
}

func letterAt(b []byte, i int) bool {
	r, _ := utf8.DecodeRune(b[i:])
	return i < len(b) && unicode.IsLetter(r)
}
